UPDATE CHB_EQUDET_SUBMIT_STATUS as A, ( select SEQNO, SUBMIT_NUM, SUBMIT_TYPE, SUBMIT_FEEDBACK_STATUS, EQUITY_CONF_DATE, REPORT_NO, SUBMIT_FEEDBACK_MSG, UNIQUE_IDENTI, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.seqno,jdbcType=VARCHAR} as SEQNO, #{item.submitNum,jdbcType=VARCHAR} as SUBMIT_NUM, #{item.submitType,jdbcType=VARCHAR} as SUBMIT_TYPE, #{item.submitFeedbackStatus,jdbcType=VARCHAR} as SUBMIT_FEEDBACK_STATUS, #{item.equityConfDate,jdbcType=DATE} as EQUITY_CONF_DATE, #{item.reportNo,jdbcType=VARCHAR} as REPORT_NO, #{item.submitFeedbackMsg,jdbcType=VARCHAR} as SUBMIT_FEEDBACK_MSG, #{item.uniqueIdenti,jdbcType=VARCHAR} as UNIQUE_IDENTI, #{item.updateUser,jdbcType=VARCHAR} as UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} as UPDATE_TIME FROM DUAL
) TEMP ) de ) AS B SET A.SUBMIT_FEEDBACK_STATUS = B.SUBMIT_FEEDBACK_STATUS, A.SUBMIT_FEEDBACK_MSG = B.SUBMIT_FEEDBACK_MSG, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME where A.REPORT_NO=B.REPORT_NO AND A.SUBMIT_NUM = B.SUBMIT_NUM;
